import{_ as u,C as l,o,c as p,a9 as a,b as n,w as t,a as s,E as r,a8 as d}from"./chunks/framework.BOiBTRPC.js";const C=JSON.parse('{"title":"Networking, Multi-Region & Landing Zones","description":"Private connectivity patterns, landing-zone topology, multi-region DR design, sovereignty constraints, and the commitment/egress math senior platform engineers actually get asked about.","frontmatter":{"title":"Networking, Multi-Region & Landing Zones","description":"Private connectivity patterns, landing-zone topology, multi-region DR design, sovereignty constraints, and the commitment/egress math senior platform engineers actually get asked about."},"headers":[],"relativePath":"cloud/platform-deep-dive.md","filePath":"cloud/platform-deep-dive.md"}'),h={name:"cloud/platform-deep-dive.md"};function g(m,e,b,v,y,f){const i=l("Mermaid"),c=l("QuizCard");return o(),p("div",null,[e[3]||(e[3]=a('<h1 id="networking-multi-region-landing-zones" tabindex="-1">Networking, Multi-Region &amp; Landing Zones <a class="header-anchor" href="#networking-multi-region-landing-zones" aria-label="Permalink to &quot;Networking, Multi-Region &amp; Landing Zones&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — The questions that separate senior platform engineers from senior analysts are infrastructure-shaped: &quot;Why can&#39;t the Databricks cluster reach the warehouse?&quot;, &quot;What&#39;s our RPO if eu-west-1 dies?&quot;, &quot;Should we commit to 3-year savings plans?&quot; These are designed-in properties, not tuning knobs — get them wrong at provisioning time and the fix is a migration.</p></blockquote><h2 id="private-connectivity-for-data-platforms" tabindex="-1">Private connectivity for data platforms <a class="header-anchor" href="#private-connectivity-for-data-platforms" aria-label="Permalink to &quot;Private connectivity for data platforms&quot;">​</a></h2><p>Every data platform eventually hits the same wall: compute in your VPC needs to reach a managed service (Snowflake, Databricks control plane, BigQuery, Redshift) or a partner&#39;s endpoint <strong>without traversing the public internet</strong>. Security teams mandate it, and it&#39;s also a performance and cost question — private paths avoid NAT gateway fees and keep egress predictable.</p><h3 id="vpc-and-subnet-design-for-compute-clusters" tabindex="-1">VPC and subnet design for compute clusters <a class="header-anchor" href="#vpc-and-subnet-design-for-compute-clusters" aria-label="Permalink to &quot;VPC and subnet design for compute clusters&quot;">​</a></h3><p>The boring rules that prevent 90% of network incidents:</p><ul><li><strong>Compute lives in private subnets.</strong> Spark clusters, Airflow workers, and ETL nodes get no public IPs. Outbound traffic (package installs, API calls) routes through a NAT gateway or an egress firewall — a controlled choke point you can log.</li><li><strong>Size subnets for the real cluster, not the diagram.</strong> A Spark cluster autoscaling to 500 workers in a /24 subnet (256 IPs) will fail at scale-up with <code>InsufficientFreeAddresses</code> — a failure that only appears on the busiest day of the year. Plan /22 or larger per compute subnet.</li><li><strong>Reserve a private subnet tier for stateful services.</strong> Managed databases and self-hosted stores (Kafka, ClickHouse) go in dedicated subnets with route tables that deny internet routes entirely.</li><li><strong>One VPC per environment, not per pipeline.</strong> VPC-per-team designs collapse under peering limits and IP overlap; consolidate and isolate with security groups and IAM instead.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Production failure mode: IP exhaustion</p><p>The classic 3am page isn&#39;t a route table bug — it&#39;s a /24 subnet that fit the dev cluster and silently can&#39;t fit prod&#39;s autoscale ceiling. Second place: NAT gateway throughput saturating because every node pulls container images through it. Both are design bugs discovered under load.</p></div><h3 id="private-endpoints-per-cloud" tabindex="-1">Private endpoints, per cloud <a class="header-anchor" href="#private-endpoints-per-cloud" aria-label="Permalink to &quot;Private endpoints, per cloud&quot;">​</a></h3><p>All three clouds offer the same primitive — a private IP inside your VPC that fronts a managed service — under different names:</p><table tabindex="0"><thead><tr><th>Capability</th><th>AWS</th><th>Azure</th><th>GCP</th></tr></thead><tbody><tr><td>Service-to-consumer primitive</td><td>PrivateLink (interface endpoint)</td><td>Private Endpoint / Private Link</td><td>Private Service Connect endpoint</td></tr><tr><td>Service-to-AWS/Azure/GCP-managed service</td><td>VPC endpoint (interface + gateway)</td><td>Private Endpoint</td><td>Private Service Connect / Private Google Access</td></tr><tr><td>Gateway-style (free) endpoints</td><td>S3, DynamoDB gateway endpoints</td><td>Service endpoints</td><td>Private Google Access for APIs</td></tr><tr><td>Publish your own service privately</td><td>NLB + endpoint service</td><td>Private Link service</td><td>PSC service attachment</td></tr><tr><td>DNS integration</td><td>Private hosted zones, <code>enableDnsHostnames</code></td><td>Private DNS zones (<code>privatelink.*</code>)</td><td>DNS zones / PSC DNS</td></tr><tr><td>Cross-org consumption</td><td>Yes, with endpoint acceptance</td><td>Yes, with approval workflow</td><td>Yes, via producer/consumer model</td></tr></tbody></table><p>The pattern to recognize: <strong>consumer pays for the endpoint, producer controls acceptance.</strong> A vendor like Snowflake publishes a PrivateLink service; you create an endpoint in your VPC; they approve the connection. DNS then resolves the service&#39;s public hostname to your private IP — which is why the private DNS zone must exist <em>before</em> you create the endpoint, or clients keep resolving public addresses.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Private endpoints fix reachability, not authorization. A PrivateLink to Snowflake means traffic stays off the internet — it does not mean only your VPC can reach the account. Combine with network policies (Snowflake <code>NETWORK_POLICY</code>, storage firewall rules, VPC SC perimeters on GCP) that reject public-source traffic, or the private path is decorative.</p></div><h3 id="vpc-peering-vs-transit-gateway-hub-spoke" tabindex="-1">VPC peering vs Transit Gateway / hub-spoke <a class="header-anchor" href="#vpc-peering-vs-transit-gateway-hub-spoke" aria-label="Permalink to &quot;VPC peering vs Transit Gateway / hub-spoke&quot;">​</a></h3><p>Point-to-point peering works until ~3 VPCs; past that it becomes an N² routing problem — peering is <strong>non-transitive</strong>, so VPC A↔B and B↔C does not give A↔C. The escape is hub-spoke:</p>',15)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-171",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Hub%5B%22Hub%20%2F%20Transit%20layer%22%5D%0A%20%20%20%20%20%20%20%20TGW%5B%22Transit%20Gateway%3Cbr%2F%3E%2F%20vWAN%20hub%20%2F%20NCC%20hub%22%5D%0A%20%20%20%20%20%20%20%20EGRESS%5B%22Shared%20egress%3Cbr%2F%3ENAT%20%2B%20inspection%20firewall%22%5D%0A%20%20%20%20%20%20%20%20DNS%5B%22Central%20DNS%3Cbr%2F%3Eresolver%20endpoints%22%5D%0A%20%20%20%20%20%20%20%20TGW%20---%20EGRESS%0A%20%20%20%20%20%20%20%20TGW%20---%20DNS%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Spokes%5B%22Workload%20VPCs%22%5D%0A%20%20%20%20%20%20%20%20DATA%5B%22Data%20platform%20VPC%3Cbr%2F%3Ewarehouse%2C%20orchestration%22%5D%0A%20%20%20%20%20%20%20%20ANALYTICS%5B%22Analytics%20VPC%3Cbr%2F%3EBI%20tools%2C%20notebooks%22%5D%0A%20%20%20%20%20%20%20%20PRODAPP%5B%22Application%20VPCs%3Cbr%2F%3Esource%20systems%22%5D%0A%20%20%20%20%20%20%20%20ONPREM%5B%22On-prem%3Cbr%2F%3Evia%20dedicated%20link%22%5D%0A%20%20%20%20end%0A%20%20%20%20TGW%20--%3E%20DATA%0A%20%20%20%20TGW%20--%3E%20ANALYTICS%0A%20%20%20%20TGW%20--%3E%20PRODAPP%0A%20%20%20%20TGW%20--%3E%20ONPREM%0A%20%20%20%20DATA%20-.-%3E%7C%22PrivateLink%22%7C%20SAAS%5B%22Managed%20services%3Cbr%2F%3ESnowflake%2C%20Databricks%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<table tabindex="0"><thead><tr><th>Model</th><th>When it wins</th><th>Breaking point</th></tr></thead><tbody><tr><td>VPC peering</td><td>2–3 VPCs, static relationships</td><td>Non-transitive; N² route tables past ~5 peers; CIDR overlap kills it</td></tr><tr><td>Transit Gateway (AWS) / vWAN (Azure) / NCC (GCP)</td><td>Many VPCs + on-prem, shared egress</td><td>Per-attachment + per-GB fees; single-hub blast radius</td></tr><tr><td>Shared VPC (GCP) / centralized egress</td><td>Org-wide standard, one security team owns egress</td><td>Blast radius and quota contention concentrated</td></tr><tr><td>Full mesh via cloud WAN</td><td>Global, multi-region transit</td><td>Cost and operational maturity required</td></tr></tbody></table><details class="details custom-block"><summary>Decision shortcut</summary><p>Fewer than ~5 VPCs, one region, no on-prem → peering is fine and cheaper. Any of: multiple regions, on-prem connectivity, &gt;5 networks, or a central security team that must inspect egress → hub-spoke, and design it before the third VPC exists. Retrofitting a transit layer under running peered VPCs means re-IPing or asymmetric routing during the migration.</p></details><h3 id="dns-and-on-prem-connectivity" tabindex="-1">DNS and on-prem connectivity <a class="header-anchor" href="#dns-and-on-prem-connectivity" aria-label="Permalink to &quot;DNS and on-prem connectivity&quot;">​</a></h3><p>Hybrid DNS is the silent killer of &quot;simple&quot; VPN setups: on-prem resolvers must resolve <code>*.privatelink.*</code> names and cloud resolvers must resolve corporate names. The standard fix is <strong>conditional forwarding in both directions</strong> — Route 53 Resolver inbound/outbound endpoints, Azure DNS Private Resolver, or Cloud DNS forwarding zones — pinned to IP addresses both sides can reach.</p><table tabindex="0"><thead><tr><th>Connectivity need</th><th>AWS</th><th>Azure</th><th>GCP</th><th>Latency / bandwidth</th><th>When to choose</th></tr></thead><tbody><tr><td>Quick, cheap hybrid</td><td>Site-to-site VPN</td><td>VPN Gateway</td><td>Cloud VPN</td><td>Variable over internet, ~1–3 Gbps/tunnel</td><td>Dev, low-volume, or backup path</td></tr><tr><td>Dedicated private line</td><td>Direct Connect</td><td>ExpressRoute</td><td>Cloud Interconnect (dedicated)</td><td>Deterministic, 1–100 Gbps</td><td>Prod data platforms, steady high-volume transfer, egress discounts</td></tr><tr><td>Partner-mediated dedicated</td><td>DX via partner</td><td>ER via provider</td><td>Partner Interconnect</td><td>Same, provisioned faster</td><td>No colo presence; telco handles last mile</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ Dedicated links change the egress math</p><p>Direct Connect and Cloud Interconnect have <em>discounted</em> egress rates versus public-internet transfer (roughly 2–4× cheaper per GB on AWS). For a data platform shipping terabytes to on-prem consumers daily, the dedicated link often pays for itself in egress savings alone — before counting the stability gain. See <a href="/Data-Knowledge/cloud/cost-architecture.html">Cost &amp; Decoupled Architecture</a> for the broader egress picture.</p></div><h2 id="the-data-platform-landing-zone" tabindex="-1">The data-platform landing zone <a class="header-anchor" href="#the-data-platform-landing-zone" aria-label="Permalink to &quot;The data-platform landing zone&quot;">​</a></h2><p>A landing zone is the opinionated account/project skeleton every workload lands in. For data platforms the topology question is where data lives relative to where compute runs:</p>',8)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-341",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20ORG%5B%22Org%20root%20%2F%20Management%20group%20%2F%20Folder%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20subgraph%20SHARED%5B%22Shared%20services%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20NET%5B%22Network%20account%3Cbr%2F%3Ehub%20VPC%2C%20DNS%2C%20egress%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20SEC%5B%22Security%20account%3Cbr%2F%3Elog%20archive%2C%20SIEM%20feed%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20IDP%5B%22Identity%3Cbr%2F%3EIdP%20federation%2C%20SSO%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20subgraph%20DATAACCT%5B%22Data%20accounts%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20PROD%5B%22data-prod%3Cbr%2F%3Ecurated%20lake%2C%20warehouse%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20NONPROD%5B%22data-nonprod%3Cbr%2F%3Edev%2C%20staging%2C%20sandbox%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20subgraph%20WORKLOAD%5B%22Workload%20accounts%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20APP1%5B%22app-team-a%3Cbr%2F%3Esource%20systems%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20APP2%5B%22app-team-b%3Cbr%2F%3Esource%20systems%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20ANALY%5B%22analytics-consumers%3Cbr%2F%3EBI%2C%20ML%20training%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A%20%20%20%20APP1%20--%3E%7C%22produce%20to%22%7C%20PROD%0A%20%20%20%20APP2%20--%3E%7C%22produce%20to%22%7C%20PROD%0A%20%20%20%20PROD%20--%3E%7C%22share%2Fserve%22%7C%20ANALY%0A%20%20%20%20NET%20--%3E%20PROD%0A%20%20%20%20NET%20--%3E%20WORKLOAD%0A%20%20%20%20SEC%20-.-%3E%7C%22read-only%20logs%22%7C%20ORG%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=a('<p>Two topologies dominate:</p><ul><li><strong>Centralized data account</strong> — one <code>data-prod</code> owns the lake and warehouse; workload accounts write via controlled ingest paths. Simpler governance, but the data account becomes a bottleneck and a billing black hole unless cost flows back out.</li><li><strong>Distributed/mesh accounts</strong> — each domain owns its data in its own account; shared account provides network and guardrails. Scales with org size but multiplies cross-account access patterns and duplication risk.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Nonprod is not optional. The single highest-leverage landing-zone decision is a hard <code>data-nonprod</code> boundary — separate account, no prod data access, cheaper guardrails. It gives you a place to break things, test IAM changes, and let analysts experiment, all without a single exception request hitting prod policy.</p></div><h3 id="iam-patterns-kill-the-long-lived-key" tabindex="-1">IAM patterns: kill the long-lived key <a class="header-anchor" href="#iam-patterns-kill-the-long-lived-key" aria-label="Permalink to &quot;IAM patterns: kill the long-lived key&quot;">​</a></h3><p>The modern landing-zone IAM posture, uniform across clouds:</p><ol><li><strong>Humans</strong> federate through the IdP (Okta/Entra/Google) into short-lived SSO sessions — no IAM users with access keys.</li><li><strong>Workload identity</strong> replaces service-account keys: AWS IAM Roles for Service Accounts (IRSA) / instance profiles, Azure workload identity federation + managed identities, GCP workload identity pools + attached service accounts. CI systems (GitHub Actions OIDC → cloud role) get short-lived tokens, never stored secrets.</li><li><strong>Cross-account access</strong> via role assumption with <code>ExternalId</code>/audience constraints — not via shared credentials.</li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk</p><p>Long-lived service-account keys are still the #1 cloud data-breach vector. Landing-zone policy should make them <em>impossible</em>, not discouraged: GCP org policy <code>iam.disableServiceAccountKeyCreation</code>, AWS SCP denying <code>iam:CreateAccessKey</code>, Azure policy blocking key auth on storage. An allowlist exception process documents the unavoidable legacy cases.</p></div><h3 id="guardrails-and-tagging" tabindex="-1">Guardrails and tagging <a class="header-anchor" href="#guardrails-and-tagging" aria-label="Permalink to &quot;Guardrails and tagging&quot;">​</a></h3><p>Enforce at the org layer so individual teams can&#39;t opt out:</p><table tabindex="0"><thead><tr><th>Guardrail</th><th>AWS</th><th>Azure</th><th>GCP</th></tr></thead><tbody><tr><td>Preventive policy</td><td>Service Control Policies</td><td>Azure Policy (deny)</td><td>Org Policy constraints</td></tr><tr><td>Allowed regions</td><td>SCP <code>aws:RequestedRegion</code></td><td>Policy location rules</td><td><code>constraints/gcp.resourceLocations</code></td></tr><tr><td>Block public buckets</td><td>S3 Block Public Access (account-level) + SCP</td><td>Storage policy <code>allowPublicAccess=false</code></td><td><code>storage.publicAccessPrevention</code></td></tr><tr><td>Enforce encryption</td><td>Deny unencrypted writes</td><td>Policy require CMK</td><td>Default CMEK + org policy</td></tr><tr><td>Key/material controls</td><td>SCP on <code>iam:*</code> mutations</td><td>Policy on RBAC/keys</td><td><code>iam.disableServiceAccountKeyCreation</code></td></tr></tbody></table><p>The tagging taxonomy from <a href="/Data-Knowledge/cloud/cost-architecture.html">Cost &amp; Decoupled Architecture</a> applies doubly here — at account level it drives both <strong>cost allocation</strong> (chargeback) and <strong>security controls</strong> (ABAC policies like &quot;dev roles can&#39;t touch <code>criticality:tier1</code> resources&quot;). Tag the workload, not the org chart; enforce required tags at deploy time via policy-as-code, not wiki convention.</p><h2 id="multi-region-architecture" tabindex="-1">Multi-region architecture <a class="header-anchor" href="#multi-region-architecture" aria-label="Permalink to &quot;Multi-region architecture&quot;">​</a></h2><p>For data platforms the honest starting question is: <em>what breaks if this region is gone for 6 hours?</em> The answer splits workloads into (a) stateful storage you must replicate and (b) stateless compute you can rebuild — and storage-compute separation (see <a href="/Data-Knowledge/cloud/big-three.html">Cloud Big Three</a>) is what makes the rebuild path cheap.</p>',13)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-495",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20RA%5B%22Region%20A%20%E2%80%94%20primary%22%5D%0A%20%20%20%20%20%20%20%20COMPUTEA%5B%22Compute%3Cbr%2F%3Ewarehouse%2C%20orchestrator%22%5D%0A%20%20%20%20%20%20%20%20STOREA%5B%22Object%20store%3Cbr%2F%3Eprimary%20replica%22%5D%0A%20%20%20%20%20%20%20%20COMPUTEA%20--%3E%20STOREA%0A%20%20%20%20end%0A%20%20%20%20subgraph%20RB%5B%22Region%20B%20%E2%80%94%20secondary%22%5D%0A%20%20%20%20%20%20%20%20COMPUTEB%5B%22Compute%3Cbr%2F%3Estandby%20or%20live%22%5D%0A%20%20%20%20%20%20%20%20STOREB%5B%22Object%20store%3Cbr%2F%3Ereplica%22%5D%0A%20%20%20%20%20%20%20%20COMPUTEB%20--%3E%20STOREB%0A%20%20%20%20end%0A%20%20%20%20STOREA%20%3D%3D%3E%7C%22async%20replication%22%7C%20STOREB%0A%20%20%20%20COMPUTEA%20-.-%3E%7C%22failover%3A%20DNS%20%2B%20config%20flip%22%7C%20COMPUTEB%0A%20%20%20%20META%5B%22Externalized%20metadata%3Cbr%2F%3Ecatalog%2C%20state%2C%20configs%22%5D%0A%20%20%20%20META%20-.-%3E%7C%22replicated%22%7C%20COMPUTEB%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=a('<h3 id="active-passive-vs-active-active" tabindex="-1">Active-passive vs active-active <a class="header-anchor" href="#active-passive-vs-active-active" aria-label="Permalink to &quot;Active-passive vs active-active&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Cost</th><th>RTO</th><th>RPO</th><th>Fit</th></tr></thead><tbody><tr><td>Backup &amp; restore</td><td>Lowest (storage only)</td><td>Hours–days</td><td>Hours (last snapshot)</td><td>Non-critical internal analytics</td></tr><tr><td>Pilot light</td><td>Replication + minimal standby</td><td>Tens of minutes</td><td>Minutes</td><td>Most data platforms — the pragmatic default</td></tr><tr><td>Warm standby</td><td>Scaled-down duplicate compute</td><td>Minutes</td><td>Minutes</td><td>Revenue-adjacent pipelines</td></tr><tr><td>Active-active</td><td>~2× cost + conflict engineering</td><td>Near zero</td><td>Near zero</td><td>Serving layers, rarely whole pipelines</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ The metadata is the hard part</p><p>Replicating <em>data</em> is a checkbox. Replicating <em>state</em> — orchestrator DAG state, checkpointed stream offsets, catalog metadata, secrets, IAM — is the actual DR problem, and it&#39;s why restore drills consistently take 3× the runbook estimate. Active-active on a data platform usually means active-active <em>storage</em> with a promoted-writer compute model, not symmetric write-anywhere.</p></div><h3 id="replication-options-per-store" tabindex="-1">Replication options per store <a class="header-anchor" href="#replication-options-per-store" aria-label="Permalink to &quot;Replication options per store&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Store</th><th>Native replication</th><th>Notes</th></tr></thead><tbody><tr><td>BigQuery</td><td>Cross-region dataset replication; managed multi-region failover via reservations</td><td>Replication is async; promotion is a manual flip — plan the runbook</td></tr><tr><td>S3</td><td>Cross-Region Replication (CRR) + replica modification sync</td><td>Versioning required; replication time control (RTC) adds SLA</td></tr><tr><td>GCS</td><td>Dual-region buckets (turbo replication, 15-min RPO SLA) or multi-region</td><td>Dual-region gives an RPO guarantee most alternatives don&#39;t</td></tr><tr><td>Snowflake</td><td>Database replication + failover groups, client redirect</td><td>Client redirect makes failover a URL, not a reconfig</td></tr><tr><td>Kafka</td><td>MirrorMaker 2 / Confluent Replicator / cluster linking</td><td>Offset translation is the trap — consumers can&#39;t just resume</td></tr><tr><td>Airflow/orchestrators</td><td>No native DR — restore state DB + redeploy DAGs</td><td>This is why &quot;backup &amp; restore&quot; RTOs balloon</td></tr></tbody></table><h3 id="region-failure-runbook-sketch" tabindex="-1">Region-failure runbook sketch <a class="header-anchor" href="#region-failure-runbook-sketch" aria-label="Permalink to &quot;Region-failure runbook sketch&quot;">​</a></h3><ol><li><strong>Detect &amp; declare</strong> — region impairment confirmed; human declares failover (automated region failover causes more outages than it prevents).</li><li><strong>Freeze ingestion</strong> — pause producers/orchestrators so no new state diverges.</li><li><strong>Promote storage</strong> — flip replica to primary (BQ dataset promotion, S3 CRR is already readable, failover group activate).</li><li><strong>Promote compute</strong> — deploy IaC-defined compute in region B (this is why compute must be fully terraformable — consoles don&#39;t failover).</li><li><strong>Redirect</strong> — DNS/client-redirect update; secrets and configs must already exist in region B.</li><li><strong>Backfill &amp; reconcile</strong> — replay from last consistent checkpoint; accept the RPO gap as duplicated-or-missing data to reconcile, not ignore.</li><li><strong>Failback is a second migration</strong> — planned, calm, scheduled. Never automatic.</li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk: drills lie unless they are destructive</p><p>A failover runbook never executed is a hypothesis. The honest test is a game day where the primary region&#39;s endpoints are actually blocked at the network layer — every shortcut that &quot;temporarily&quot; points at region A reveals itself instantly. Run it annually, and time every step: measured RTO beats documented RTO.</p></div><h2 id="sovereignty-and-compliance-brief" tabindex="-1">Sovereignty and compliance brief <a class="header-anchor" href="#sovereignty-and-compliance-brief" aria-label="Permalink to &quot;Sovereignty and compliance brief&quot;">​</a></h2><p>Data-residency requirements moved from contractual checkbox to engineered feature. What&#39;s actually on the table:</p><ul><li><strong>AWS European Sovereign Cloud</strong> — a physically and logically separate AWS partition in Germany, EU-operated, launched to satisfy EU sovereignty demands. Distinct from &quot;just use eu-* regions.&quot;</li><li><strong>Microsoft EU Data Boundary</strong> — commitment that customer data for core services is stored and processed within the EU; plus Sovereign Public/Private Cloud and National Partner Cloud tiers.</li><li><strong>GCP</strong> — sovereignty via data-residency controls (org policy <code>gcp.resourceLocations</code>, in-country processing options like sovereign controls partners e.g. T-Systems/S3NS), plus Assured Workloads for regulated workloads.</li><li><strong>In-country processing</strong> — all three offer region-pinning guardrails; the engineering work is proving <em>processing</em> (not just storage) stays in-boundary, which means auditing every managed service&#39;s control plane and support-access paths, not just bucket location.</li></ul><table tabindex="0"><thead><tr><th>Need</th><th>AWS</th><th>Azure</th><th>GCP</th></tr></thead><tbody><tr><td>Boundary commitment</td><td>European Sovereign Cloud (separate partition, in progress)</td><td>EU Data Boundary (store + process in EU)</td><td>Assured Workloads + sovereign partner controls</td></tr><tr><td>Region pinning</td><td>SCP <code>aws:RequestedRegion</code></td><td>Azure Policy allowed locations</td><td>Org policy <code>gcp.resourceLocations</code></td></tr><tr><td>Key residency</td><td>External key store / HYOK</td><td>Managed HSM, CMK</td><td>EKM / Cloud HSM, CMEK everywhere</td></tr><tr><td>Operator access control</td><td>Sovereign ops staffing model</td><td>Customer Lockbox</td><td>Access Transparency + Access Approval</td></tr></tbody></table><p>Key residency deserves its own line because it&#39;s the control that actually bites: an EU-bounded bucket decrypted by an operator with global key access isn&#39;t sovereign in any regulator&#39;s view. Customer-managed keys with in-boundary HSMs turn a policy promise into a technical constraint — expensive and operationally heavier, but it&#39;s the version that survives audit.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk: metadata leaves the boundary</p><p>Bucket location <code>eu</code> doesn&#39;t mean your <em>logs, telemetry, billing records, and support transcripts</em> are in the EU. Sovereignty audits that check only storage location miss the most common violation path. The EU Data Boundary-style commitments exist precisely because this gap was discovered.</p></div><h2 id="advanced-finops" tabindex="-1">Advanced FinOps <a class="header-anchor" href="#advanced-finops" aria-label="Permalink to &quot;Advanced FinOps&quot;">​</a></h2><p><a href="/Data-Knowledge/cloud/cost-architecture.html">Cost &amp; Decoupled Architecture</a> covers attribution and guardrails; this section is the strategy layer.</p><h3 id="commitment-strategy" tabindex="-1">Commitment strategy <a class="header-anchor" href="#commitment-strategy" aria-label="Permalink to &quot;Commitment strategy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Instrument</th><th>Cloud</th><th>Scope</th><th>Flexibility</th><th>Discount</th></tr></thead><tbody><tr><td>Reserved Instances</td><td>AWS / Azure (reservations)</td><td>Specific instance family/region</td><td>Low–medium (convertible/exchange options)</td><td>Up to ~72%</td></tr><tr><td>Savings Plans</td><td>AWS (Compute/EC2/SageMaker SP)</td><td>$/hour spend commitment</td><td>High — floats across families/regions</td><td>Up to ~66–72%</td></tr><tr><td>Committed Use Discounts</td><td>GCP (CUDs, spend- or resource-based)</td><td>vCPU/RAM or $ spend</td><td>High for spend-based</td><td>Up to ~57–70%</td></tr><tr><td>Capacity reservations</td><td>All three</td><td>Guaranteed capacity, not price</td><td>Separate concern — don&#39;t confuse</td><td>None (or paired with above)</td></tr></tbody></table><p>Rules that survive contact with finance:</p><ul><li><strong>Commit to the floor, not the average.</strong> Chart daily-minimum usage over 90 days; commit to ~70–80% of the floor. Committing to average utilization means paying for troughs.</li><li><strong>1-year first, 3-year only for proven-stable baseload.</strong> A 3-year commitment on an architecture you might migrate (lakehouse→warehouse, region move) is a lock-in tax layered on the vendor lock-in below.</li><li><strong>Ladder commitments.</strong> Buy quarterly tranches instead of one annual tranche — expirations stagger, so a workload change never strands the whole commitment at once.</li><li><strong>Separate compute shape from spend.</strong> Prefer spend-based instruments (Savings Plans, spend-based CUDs) — instance-family reservations strand when you right-size.</li></ul><h3 id="unit-economics-of-a-data-team" tabindex="-1">Unit economics of a data team <a class="header-anchor" href="#unit-economics-of-a-data-team" aria-label="Permalink to &quot;Unit economics of a data team&quot;">​</a></h3><p>Total-platform-cost ÷ useful-work is the only number executives can compare across teams. Practical denominators:</p><ul><li><strong>Cost per TB processed</strong> — normalizes for growth; good for pipeline teams. Watch it trend, don&#39;t benchmark absolutes (a CDC pipeline and a scan-heavy analytics job have legitimately different unit costs).</li><li><strong>Cost per delivered data product / per active consumer</strong> — ties spend to output, not input. Best for proving platform ROI.</li><li><strong>Marginal cost of the next workload</strong> — what it <em>actually costs</em> to onboard one more pipeline on existing commitments. Usually near zero until you hit a commitment boundary — which is when onboarding reviews matter.</li></ul><h3 id="showback-chargeback-anomaly-detection" tabindex="-1">Showback, chargeback, anomaly detection <a class="header-anchor" href="#showback-chargeback-anomaly-detection" aria-label="Permalink to &quot;Showback, chargeback, anomaly detection&quot;">​</a></h3><ul><li><strong>Showback first.</strong> Report cost per team for 2–3 quarters before charging anyone — chargeback against untrusted allocation starts political fights that end in sticker-tag chaos.</li><li><strong>Chargeback with a floor.</strong> Shared platform costs (network, control planes, the unlabeled tail) go into a platform tax allocated pro-rata; usage-based spend charges directly. Pure pass-through chargeback makes teams hostile to shared infrastructure.</li><li><strong>Anomaly detection on spend, not just budgets.</strong> Day-over-day delta per tag catches the runaway query in hours; monthly budget alerts catch it at the invoice. Cloud-native (Cost Anomaly Detection, GCP/AWS billing anomaly services) works — the gap is routing: an anomaly alert that lands in a finance mailbox is a decoration. Route to the owning team&#39;s channel via the tag.</li></ul><h2 id="vendor-lock-in-escape-economics" tabindex="-1">Vendor lock-in escape economics <a class="header-anchor" href="#vendor-lock-in-escape-economics" aria-label="Permalink to &quot;Vendor lock-in escape economics&quot;">​</a></h2><p>Egress pricing is the tariff wall around every data platform. Worked example — <strong>1 PB of data out to the internet</strong>, list prices, approximate tiered rates:</p><table tabindex="0"><thead><tr><th>Cloud</th><th>Tiered math (approx.)</th><th>~1 PB egress</th></tr></thead><tbody><tr><td>AWS</td><td>10 TB × $0.09 + 40 TB × $0.085 + 100 TB × $0.07 + rest × $0.05</td><td><strong>≈ $55–60k</strong></td></tr><tr><td>Azure</td><td>Similar tiers, ~$0.087 → ~$0.05</td><td><strong>≈ $55–60k</strong></td></tr><tr><td>GCP</td><td>Premium tier ~$0.08–0.12/GB by region; standard lower</td><td><strong>≈ $60–90k</strong></td></tr></tbody></table><p>Plus what the table hides: request charges, cross-AZ transfer to reach the egress point, <em>doubling</em> cost if you first replicate to a second region, and the parallel-write period where you pay both clouds.</p><p>The cheaper exit is <strong>replication-based migration</strong>: stand up the target platform, replicate incrementally (object-store sync, CDC streams), cut over consumers, then drain — converting a cliff-edge egress event into months of smaller transfers, and letting you validate before committing. Total cost is still substantial; what changes is risk and timing, not the physics.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight: the free-egress exit door</p><p>Following EU Data Act pressure, all three clouds now waive egress fees for customers <strong>migrating entirely off the platform</strong> (typically requires closing the account or approval). This helps the once-ever migration but does nothing for multi-cloud or repatriation-partial patterns — and approval isn&#39;t automatic. Know the policy exists; don&#39;t architect assuming it applies.</p></div><p>The real senior-engineer take: <strong>portable formats beat portable infrastructure.</strong> Keeping the lake in open table formats (Iceberg/Delta) and open file formats (Parquet) means a migration moves bytes, not logic — the egress bill is fixed, but the rewrite bill, which is usually 5–10× the egress bill in labor, collapses.</p><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',33)),r(c,{questions:[{q:"A Spark cluster fails at scale-up on the busiest day with IP exhaustion. Root cause?",options:["Too many security groups","Subnet sized for dev — e.g. a /24 cannot fit the prod autoscale ceiling","DNS resolver throttling","Route table misconfiguration"],correct:1,explain:"IP exhaustion is a design-time bug that only manifests under peak load. Compute subnets should be sized (e.g. /22+) for the autoscale ceiling, not the average footprint."},{q:"What does PrivateLink / Private Endpoint / PSC actually change?",options:["It encrypts data that was previously unencrypted","It gives the managed service a private IP inside your VPC so traffic stays off the public internet","It authorizes which identities may call the service","It removes the need for a private DNS zone"],correct:1,explain:"Private endpoints fix reachability, not authorization — you still need network policies that reject public-source traffic. And they depend on private DNS resolving the service hostname to the private IP."},{q:"When should you choose hub-spoke over VPC peering?",options:["Whenever two VPCs exist","Only for on-prem VPN links","Multiple regions, more than ~5 networks, on-prem connectivity, or centralized egress inspection","Only when peering costs exceed transit fees"],correct:2,explain:"Peering is non-transitive and becomes an N-squared route-table problem. Any of multi-region, on-prem links, many VPCs, or a central security team needing egress inspection justifies the transit layer."},{q:"What usually breaks first in a real region-failover drill?",options:["Externalized metadata and state — orchestrator state, stream offsets, catalogs, secrets","Compute autoscaling","Object storage replication","NAT gateway capacity"],correct:0,explain:"Data replication is a checkbox; replicating orchestrator state, checkpointed offsets, catalog metadata, and secrets is the real DR problem — which is why drills run 3x the runbook estimate."},{q:"Right commitment strategy for volatile-but-growing data workloads?",options:["Stay fully on-demand until spend exceeds $1M/yr","Three-year all-in reservations for max discount","Commit to average usage with instance-family reservations","Commit to the daily-minimum floor, prefer spend-based instruments, ladder purchases quarterly"],correct:3,explain:"Commit to ~70-80% of the floor (not the average), prefer Savings Plans / spend-based CUDs so the discount floats across instance shapes, and ladder tranches so a workload change never strands everything."},{q:"Cheapest realistic path to migrate a 1 PB data platform off a cloud?",options:["Compress the data first to cut egress volume 10x","Bulk export once and pay the ~$60k egress bill","Peer the two clouds privately so egress is free","Replication-based migration: incremental sync plus CDC, parallel-run, then cut over — trades the cliff-edge bill for staged transfers and validation time"],correct:3,explain:"Replication-based migration converts one risky egress event into staged transfers with validation. The all-in-one-shot option risks a failed cutover after paying; compression does not reach 10x on already-columnar data; all-clouds also offer free egress only for full account-closing exits."}]}),e[7]||(e[7]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.aws.amazon.com/vpc/latest/privatelink/what-is-privatelink.html" target="_blank" rel="noreferrer">AWS PrivateLink documentation</a></li><li><a href="https://learn.microsoft.com/en-us/azure/private-link/private-link-overview" target="_blank" rel="noreferrer">Azure Private Link documentation</a></li><li><a href="https://cloud.google.com/vpc/docs/private-service-connect" target="_blank" rel="noreferrer">Google Cloud Private Service Connect</a></li><li><a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/establishing-a-data-perimeter-on-aws/welcome.html" target="_blank" rel="noreferrer">AWS Prescriptive Guidance — Establishing a data perimeter on AWS</a></li><li><a href="https://cloud.google.com/bigquery/docs/data-replication" target="_blank" rel="noreferrer">BigQuery cross-region dataset replication</a></li><li><a href="https://learn.microsoft.com/en-us/industry/sovereignty/eu-data-boundary" target="_blank" rel="noreferrer">Microsoft EU Data Boundary</a></li><li><a href="https://d1.awsstatic.com/onedam/marketing-channels/website/aws/en_US/whitepapers/compliance/Overview_of_the_AWS_European_Sovereign_Cloud.pdf" target="_blank" rel="noreferrer">AWS European Sovereign Cloud overview (PDF)</a></li><li><a href="https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/welcome.html" target="_blank" rel="noreferrer">AWS Well-Architected — Reliability pillar, disaster recovery</a></li></ul>',2))])}const A=u(h,[["render",g]]);export{C as __pageData,A as default};
